=== FILE: rtl/axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with a level interrupt.
// Implements axil_timer_microarchitecture_spec.md section 5 (sha256:1e77972d...)
// for interface spec axil_timer_interface_spec.md (sha256:3667d985...).
// Traces to requirement req-2b2b91a584.
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State elements (uarch section 2)
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held_q;
    reg [31:0]           wdata_q;
    reg [3:0]            wstrb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;
    reg                  irq_q;

    // ------------------------------------------------------------------
    // Handshakes (uarch 5.1)
    // ------------------------------------------------------------------
    wire awready_w = !aw_held_q && !bvalid_q;
    wire wready_w  = !w_held_q  && !bvalid_q;
    wire arready_w = !rvalid_q;

    wire aw_fire = s_axil_awvalid && awready_w;
    wire w_fire  = s_axil_wvalid  && wready_w;
    wire ar_fire = s_axil_arvalid && arready_w;

    // ------------------------------------------------------------------
    // Write join (uarch 5.2)
    // ------------------------------------------------------------------
    wire wr_go = (aw_fire && w_fire) || (aw_fire && w_held_q) || (w_fire && aw_held_q);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q  ? wdata_q   : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q  ? wstrb_q   : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Decode (uarch 5.3)
    // ------------------------------------------------------------------
    wire wr_upper_zero;
    wire rd_upper_zero;

    generate
        if (ADDR_WIDTH > 4) begin : g_upper
            assign wr_upper_zero = (wr_addr[ADDR_WIDTH-1:4]       == {(ADDR_WIDTH-4){1'b0}});
            assign rd_upper_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
        end else begin : g_no_upper
            assign wr_upper_zero = 1'b1;
            assign rd_upper_zero = 1'b1;
        end
    endgenerate

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_upper_zero;
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_upper_zero;
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    // ------------------------------------------------------------------
    // Write effects (uarch 5.4)
    // ------------------------------------------------------------------
    wire       wm        = wr_go && wr_mapped;
    wire       ctrl_wr   = wm && (wr_idx == 2'd0) && wr_strb[0];
    wire [3:0] load_wr_b = (wm && (wr_idx == 2'd1)) ? wr_strb : 4'b0000;
    wire       stat_clr  = wm && (wr_idx == 2'd3) && wr_strb[0] && wr_data[0];
    wire       start     = ctrl_wr && wr_data[0];
    wire       wr_slverr = !wr_mapped || (wr_idx == 2'd2);

    // ------------------------------------------------------------------
    // Read value (uarch 5.5): pre-edge flop values only
    // ------------------------------------------------------------------
    reg [31:0] rd_val;
    always @* begin
        rd_val = 32'h0000_0000;
        if (rd_mapped) begin
            case (rd_idx)
                2'd0:    rd_val = {29'd0, mode_q, ie_q, en_q};
                2'd1:    rd_val = load_q;
                2'd2:    rd_val = count_q;
                default: rd_val = {31'd0, expired_q};
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Timer core (uarch 5.6)
    // ------------------------------------------------------------------
    wire        cnt_end   = en_q && ((count_q == 32'd0) || (count_q == 32'd1));
    wire [31:0] count_dec = count_q - 32'd1;

    reg [31:0] count_d;
    always @* begin
        if (start)
            count_d = load_q;
        else if (cnt_end)
            count_d = mode_q ? load_q : 32'd0;
        else if (en_q)
            count_d = count_dec;
        else
            count_d = count_q;
    end

    wire en_d      = ctrl_wr ? wr_data[0] : ((cnt_end && !mode_q) ? 1'b0 : en_q);
    wire ie_d      = ctrl_wr ? wr_data[1] : ie_q;
    wire mode_d    = ctrl_wr ? wr_data[2] : mode_q;
    wire expired_d = cnt_end ? 1'b1 : (stat_clr ? 1'b0 : expired_q);
    wire irq_d     = expired_d && ie_d;

    wire [31:0] load_d = {
        load_wr_b[3] ? wr_data[31:24] : load_q[31:24],
        load_wr_b[2] ? wr_data[23:16] : load_q[23:16],
        load_wr_b[1] ? wr_data[15:8]  : load_q[15:8],
        load_wr_b[0] ? wr_data[7:0]   : load_q[7:0]
    };

    // ------------------------------------------------------------------
    // Sequential logic with synchronous active-low reset (uarch 5.7)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            wdata_q   <= 32'd0;
            wstrb_q   <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= 32'd0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
            expired_q <= 1'b0;
            irq_q     <= 1'b0;
        end else begin
            // AW holding register
            if (aw_held_q && w_fire)
                aw_held_q <= 1'b0;
            else if (aw_fire && !w_fire && !w_held_q)
                aw_held_q <= 1'b1;
            if (aw_fire)
                aw_addr_q <= s_axil_awaddr;

            // W holding register
            if (w_held_q && aw_fire)
                w_held_q <= 1'b0;
            else if (w_fire && !aw_fire && !aw_held_q)
                w_held_q <= 1'b1;
            if (w_fire) begin
                wdata_q <= s_axil_wdata;
                wstrb_q <= s_axil_wstrb;
            end

            // B response
            if (wr_go) begin
                bvalid_q <= 1'b1;
                bresp_q  <= wr_slverr ? RESP_SLVERR : RESP_OKAY;
            end else if (s_axil_bready) begin
                bvalid_q <= 1'b0;
            end

            // R response
            if (ar_fire) begin
                rvalid_q <= 1'b1;
                rdata_q  <= rd_val;
                rresp_q  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_rready) begin
                rvalid_q <= 1'b0;
            end

            // Register file and timer core
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            load_q    <= load_d;
            count_q   <= count_d;
            expired_q <= expired_d;
            irq_q     <= irq_d;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready_w;
    assign s_axil_wready  = wready_w;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready_w;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;
    assign irq            = irq_q;

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb/tb_axil_timer.v ===
// Self-checking testbench for axil_timer (Icarus Verilog).
// Instantiates the block at ADDR_WIDTH 4 and 8 and runs the suite on each.
// Traces to requirement req-2b2b91a584, interface spec sections 3 to 8.
`timescale 1ns/1ps
`default_nettype none

module tb_axil_timer;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;
    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;

    reg         clk     = 1'b0;
    reg         rst_n   = 1'b0;
    reg         sel     = 1'b0;
    reg  [7:0]  awaddr  = 8'h00;
    reg         awvalid = 1'b0;
    reg  [31:0] wdata   = 32'h0;
    reg  [3:0]  wstrb   = 4'h0;
    reg         wvalid  = 1'b0;
    reg         bready  = 1'b1;
    reg  [7:0]  araddr  = 8'h00;
    reg         arvalid = 1'b0;
    reg         rready  = 1'b1;

    integer passed = 0;
    integer failed = 0;
    integer cyc    = 0;
    integer E;
    integer R;
    integer i;
    reg [7:0]      ai;
    reg            ld_old;
    reg [8*64-1:0] nonce;

    reg        wr_iss = 1'b0;
    reg        rd_iss = 1'b0;
    reg [1:0]  last_bresp = 2'b00;
    reg [1:0]  last_rresp = 2'b00;
    reg [31:0] last_rdata = 32'h0;
    reg [31:0] held_rdata = 32'h0;

    always #5 clk = ~clk;

    // ---------------- DUT, ADDR_WIDTH = 4 ----------------
    wire        aw4, w4, b4v, ar4, r4v, irq4;
    wire [1:0]  b4r, r4r;
    wire [31:0] r4d;

    axil_timer #(.ADDR_WIDTH(4)) u_dut4 (
        .aclk(clk), .aresetn(rst_n),
        .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid & ~sel), .s_axil_awready(aw4),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & ~sel), .s_axil_wready(w4),
        .s_axil_bresp(b4r), .s_axil_bvalid(b4v), .s_axil_bready(bready),
        .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid & ~sel), .s_axil_arready(ar4),
        .s_axil_rdata(r4d), .s_axil_rresp(r4r), .s_axil_rvalid(r4v), .s_axil_rready(rready),
        .irq(irq4)
    );

    // ---------------- DUT, ADDR_WIDTH = 8 ----------------
    wire        aw8, w8, b8v, ar8, r8v, irq8;
    wire [1:0]  b8r, r8r;
    wire [31:0] r8d;

    axil_timer #(.ADDR_WIDTH(8)) u_dut8 (
        .aclk(clk), .aresetn(rst_n),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid & sel), .s_axil_awready(aw8),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & sel), .s_axil_wready(w8),
        .s_axil_bresp(b8r), .s_axil_bvalid(b8v), .s_axil_bready(bready),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid & sel), .s_axil_arready(ar8),
        .s_axil_rdata(r8d), .s_axil_rresp(r8r), .s_axil_rvalid(r8v), .s_axil_rready(rready),
        .irq(irq8)
    );

    // Selected DUT outputs
    wire        awready = sel ? aw8  : aw4;
    wire        wready  = sel ? w8   : w4;
    wire        bvalid  = sel ? b8v  : b4v;
    wire [1:0]  bresp   = sel ? b8r  : b4r;
    wire        arready = sel ? ar8  : ar4;
    wire        rvalid  = sel ? r8v  : r4v;
    wire [1:0]  rresp   = sel ? r8r  : r4r;
    wire [31:0] rdata   = sel ? r8d  : r4d;
    wire        irq     = sel ? irq8 : irq4;

    // ---------------- check helpers ----------------
    task chk(input c, input [8*96-1:0] msg);
        begin
            if (c === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED (aw=%0d cyc=%0d): %0s", sel ? 8 : 4, cyc, msg);
            end
        end
    endtask

    task chk_eq(input [31:0] got, input [31:0] expv, input [8*96-1:0] msg);
        begin
            if (got === expv) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED (aw=%0d cyc=%0d): %0s: got 0x%08h expected 0x%08h",
                       sel ? 8 : 4, cyc, msg, got, expv);
            end
        end
    endtask

    task mchk(input c, input [8*96-1:0] msg);
        begin
            if (c === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("MONITOR FAILED (aw=%0d cyc=%0d): %0s", sel ? 8 : 4, cyc, msg);
            end
        end
    endtask

    // ---------------- protocol monitor (IS 3) ----------------
    reg        m_valid   = 1'b0;
    reg        m_pend_aw = 1'b0;
    reg        m_pend_w  = 1'b0;
    reg        m_exp_b   = 1'b0;
    reg        m_exp_r   = 1'b0;
    reg        m_bhold   = 1'b0;
    reg        m_rhold   = 1'b0;
    reg [1:0]  m_bresp   = 2'b00;
    reg [1:0]  m_rresp   = 2'b00;
    reg [31:0] m_rdata   = 32'h0;
    reg        m_aw_acc, m_w_acc, m_ar_acc, m_complete;

    always @(posedge clk) begin
        // Values seen here are the ones produced by the previous edge.
        if (m_valid) begin
            mchk(bvalid === m_exp_b, "bvalid: high exactly after completing edge, held until bready");
            mchk(rvalid === m_exp_r, "rvalid: high exactly after AR accept, held until rready");
            if (m_bhold) mchk(bresp === m_bresp, "bresp stable while bvalid waits");
            if (m_rhold) mchk((rresp === m_rresp) && (rdata === m_rdata), "rresp/rdata stable while rvalid waits");
            mchk(awready === (!m_pend_aw && !bvalid), "awready == !aw_held && !bvalid");
            mchk(wready  === (!m_pend_w  && !bvalid), "wready == !w_held && !bvalid");
            mchk(arready === (!rvalid), "arready == !rvalid");
        end
        if (!rst_n) begin
            m_pend_aw = 1'b0;
            m_pend_w  = 1'b0;
            m_exp_b   = 1'b0;
            m_exp_r   = 1'b0;
            m_bhold   = 1'b0;
            m_rhold   = 1'b0;
            m_valid   = 1'b1;
        end else if (m_valid) begin
            m_aw_acc   = awvalid && awready;
            m_w_acc    = wvalid && wready;
            m_ar_acc   = arvalid && arready;
            m_complete = (m_aw_acc || m_pend_aw) && (m_w_acc || m_pend_w);
            m_exp_b    = m_complete ? 1'b1 : (bvalid && !bready);
            if (m_complete) begin
                m_pend_aw = 1'b0;
                m_pend_w  = 1'b0;
            end else begin
                if (m_aw_acc) m_pend_aw = 1'b1;
                if (m_w_acc)  m_pend_w  = 1'b1;
            end
            m_exp_r = m_ar_acc ? 1'b1 : (rvalid && !rready);
            m_bhold = bvalid && !bready;
            m_bresp = bresp;
            m_rhold = rvalid && !rready;
            m_rresp = rresp;
            m_rdata = rdata;
        end
    end

    // ---------------- stimulus helpers ----------------
    // After tick, time is 1 ns past edge number cyc; outputs show after-edge values.
    task tick;
        begin
            @(posedge clk);
            #1;
            cyc = cyc + 1;
        end
    endtask

    // Wait so that the next edge is edge a.
    task go_to(input integer a);
        begin
            if (cyc > a - 1) begin
                failed = failed + 1;
                $error("SCHEDULE ERROR: at cyc %0d, wanted edge %0d", cyc, a);
            end
            while (cyc < a - 1) tick;
        end
    endtask

    // Wait until just after edge a.
    task at(input integer a);
        begin
            if (cyc > a) begin
                failed = failed + 1;
                $error("SCHEDULE ERROR: at cyc %0d, wanted after edge %0d", cyc, a);
            end
            while (cyc < a) tick;
        end
    endtask

    task set_wr(input [7:0] a, input [31:0] d, input [3:0] s);
        begin
            chk((awready === 1'b1) && (wready === 1'b1), "write issue: awready and wready high");
            awaddr = a; wdata = d; wstrb = s;
            awvalid = 1'b1; wvalid = 1'b1; wr_iss = 1'b1;
        end
    endtask

    task set_rd(input [7:0] a);
        begin
            chk(arready === 1'b1, "read issue: arready high");
            araddr = a; arvalid = 1'b1; rd_iss = 1'b1;
        end
    endtask

    task step;
        begin
            tick;
            if (wr_iss) begin
                awvalid = 1'b0; wvalid = 1'b0; wr_iss = 1'b0;
                chk(bvalid === 1'b1, "bvalid high right after completing edge");
                last_bresp = bresp;
            end
            if (rd_iss) begin
                arvalid = 1'b0; rd_iss = 1'b0;
                chk(rvalid === 1'b1, "rvalid high right after AR accept edge");
                last_rresp = rresp;
                last_rdata = rdata;
            end
        end
    endtask

    task chk_rd(input [31:0] expv, input [1:0] er, input [8*96-1:0] msg);
        begin
            chk_eq(last_rdata, expv, msg);
            chk_eq({30'd0, last_rresp}, {30'd0, er}, "read response code");
        end
    endtask

    task wr(input [7:0] a, input [31:0] d, input [3:0] s, input [1:0] er);
        begin
            while (!((awready === 1'b1) && (wready === 1'b1))) tick;
            set_wr(a, d, s);
            step;
            chk_eq({30'd0, last_bresp}, {30'd0, er}, "write response code");
            tick;
        end
    endtask

    task rd(input [7:0] a, input [31:0] expv, input [1:0] er);
        begin
            while (arready !== 1'b1) tick;
            set_rd(a);
            step;
            chk_rd(expv, er, "read data");
            tick;
        end
    endtask

    task do_reset;
        begin
            awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
            bready = 1'b1; rready = 1'b1; wr_iss = 1'b0; rd_iss = 1'b0;
            rst_n = 1'b0;
            tick;
            tick;
            rst_n = 1'b1;
            chk((bvalid === 1'b0) && (rvalid === 1'b0) && (irq === 1'b0), "reset: bvalid, rvalid, irq low");
            chk((awready === 1'b1) && (wready === 1'b1) && (arready === 1'b1), "reset: all readies high");
        end
    endtask

    // ---------------- test suite (both widths) ----------------
    task run_suite;
        begin
            // ---- T1: reset values
            do_reset;
            rd(A_CTRL, 32'h0, OKAY);
            rd(A_LOAD, 32'h0, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);

            // ---- T2: register access, strobes, SLVERR, decode
            wr(A_LOAD, 32'h12345678, 4'hF, OKAY);    rd(A_LOAD, 32'h12345678, OKAY);
            wr(A_LOAD, 32'hAABBCCDD, 4'b0101, OKAY); rd(A_LOAD, 32'h12BB56DD, OKAY);
            wr(A_LOAD, 32'hFFFFFFFF, 4'b0000, OKAY); rd(A_LOAD, 32'h12BB56DD, OKAY);
            wr(A_LOAD, 32'h11223344, 4'b1010, OKAY); rd(A_LOAD, 32'h11BB33DD, OKAY);
            wr(A_CTRL, 32'hFFFFFFFE, 4'hF, OKAY);    rd(A_CTRL, 32'h6, OKAY);
            wr(A_CTRL, 32'h00000001, 4'b1110, OKAY); rd(A_CTRL, 32'h6, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            wr(A_CTRL, 32'h0, 4'b0001, OKAY);        rd(A_CTRL, 32'h0, OKAY);
            wr(A_COUNT, 32'h55, 4'hF, SLVERR);       rd(A_COUNT, 32'h0, OKAY);
            wr(A_STATUS, 32'hFFFFFFFF, 4'hF, OKAY);  rd(A_STATUS, 32'h0, OKAY);
            for (ai = 8'h00; ai < 8'h10; ai = ai + 8'h01) begin
                if (ai[1:0] != 2'b00) begin
                    wr(ai, 32'hFFFFFFFF, 4'hF, SLVERR);
                    rd(ai, 32'h0, SLVERR);
                end
            end
            rd(A_CTRL, 32'h0, OKAY);
            rd(A_LOAD, 32'h11BB33DD, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);

            // ---- T3: one-shot end timing, irq, IE raise
            do_reset;
            wr(A_LOAD, 32'd4, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h3, 4'h1); step; E = cyc;
            for (i = 0; i < 4; i = i + 1) begin
                at(E + i);
                chk(irq === 1'b0, "irq low before one-shot end");
            end
            at(E + 4);
            chk(irq === 1'b1, "irq high right after end edge E+N");
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            set_wr(A_STATUS, 32'h1, 4'h1); step;
            chk(irq === 1'b0, "irq low right after STATUS clear edge");
            for (i = 0; i < 10; i = i + 1) begin
                tick;
                chk(irq === 1'b0, "no further end after one-shot");
            end
            rd(A_STATUS, 32'h0, OKAY);
            rd(A_COUNT, 32'h0, OKAY);

            wr(A_LOAD, 32'd2, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            at(E + 2);
            chk(irq === 1'b0, "irq low with EXPIRED set and IE 0");
            rd(A_STATUS, 32'h1, OKAY);
            set_wr(A_CTRL, 32'h2, 4'h1); step;
            chk(irq === 1'b1, "irq high right after IE write with EXPIRED set");
            tick;
            set_wr(A_CTRL, 32'h0, 4'h1); step;
            chk(irq === 1'b0, "irq low right after IE cleared");
            tick;
            wr(A_STATUS, 32'h1, 4'h1, OKAY);
            rd(A_STATUS, 32'h0, OKAY);

            // ---- T4: COUNT readback, one-shot N=6
            do_reset;
            wr(A_LOAD, 32'd6, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 1); set_rd(A_COUNT); step; chk_rd(32'd6, OKAY, "COUNT after E is N");
            go_to(E + 3); set_rd(A_COUNT); step; chk_rd(32'd4, OKAY, "COUNT after E+2");
            go_to(E + 5); set_rd(A_COUNT); step; chk_rd(32'd2, OKAY, "COUNT after E+4");
            go_to(E + 7); set_rd(A_COUNT); step; chk_rd(32'd0, OKAY, "COUNT 0 after one-shot end");
            rd(A_STATUS, 32'h1, OKAY);
            rd(A_CTRL, 32'h0, OKAY);
            chk(irq === 1'b0, "irq stays low with IE 0");
            wr(A_STATUS, 32'h1, 4'h1, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 2); set_rd(A_COUNT); step; chk_rd(32'd5, OKAY, "COUNT after E+1");
            go_to(E + 4); set_rd(A_COUNT); step; chk_rd(32'd3, OKAY, "COUNT after E+3");
            go_to(E + 6); set_rd(A_COUNT); step; chk_rd(32'd1, OKAY, "COUNT after E+5");
            go_to(E + 8); set_rd(A_COUNT); step; chk_rd(32'd0, OKAY, "COUNT after E+7");

            // ---- T5: periodic, EXPIRED clear, end beats clear, stop
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h7, 4'h1); step; E = cyc;
            go_to(E + 3); chk(irq === 1'b0, "periodic: irq low before first end");
            step;         chk(irq === 1'b1, "periodic: irq high after E+N");
            go_to(E + 4); set_rd(A_COUNT); set_wr(A_STATUS, 32'h1, 4'h1); step;
            chk_rd(32'd3, OKAY, "periodic reload to LOAD");
            chk(irq === 1'b0, "periodic: clear on non-end edge drops irq");
            go_to(E + 6); set_rd(A_COUNT); step;
            chk_rd(32'd1, OKAY, "periodic COUNT after E+5");
            chk(irq === 1'b1, "periodic: second end sets irq");
            go_to(E + 8); set_rd(A_COUNT); step;
            chk_rd(32'd2, OKAY, "periodic COUNT after E+7");
            go_to(E + 9); set_wr(A_STATUS, 32'h1, 4'h1); step;
            chk(irq === 1'b1, "end beats STATUS clear (periodic)");
            go_to(E + 10); set_rd(A_COUNT); step;
            chk_rd(32'd3, OKAY, "reload while EXPIRED already set");
            go_to(E + 11); set_wr(A_STATUS, 32'h1, 4'h1); step;
            chk(irq === 1'b0, "clear on non-end edge");
            go_to(E + 12); set_rd(A_STATUS); step;
            chk_rd(32'h0, OKAY, "STATUS before E+12 end is 0");
            chk(irq === 1'b1, "end at E+12 sets irq");
            go_to(E + 14); set_wr(A_CTRL, 32'h6, 4'h1); set_rd(A_COUNT); step;
            chk_rd(32'd2, OKAY, "COUNT before stop edge");
            go_to(E + 16); set_rd(A_COUNT); step;
            chk_rd(32'd1, OKAY, "stop edge still decrements");
            go_to(E + 20); set_rd(A_COUNT); step;
            chk_rd(32'd1, OKAY, "COUNT holds after stop");
            rd(A_CTRL, 32'h6, OKAY);
            chk(irq === 1'b1, "irq unchanged by stop");
            wr(A_CTRL, 32'h6, 4'h1, OKAY);
            rd(A_COUNT, 32'd1, OKAY);

            // ---- T6: restart applies new MODE
            do_reset;
            wr(A_LOAD, 32'd5, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h5, 4'h1); step; E = cyc;
            go_to(E + 2); set_wr(A_CTRL, 32'h1, 4'h1); step; R = cyc;
            go_to(R + 1); set_rd(A_COUNT); step;  chk_rd(32'd5, OKAY, "restart reloads LOAD");
            go_to(R + 3); set_rd(A_COUNT); step;  chk_rd(32'd3, OKAY, "restart COUNT after R+2");
            go_to(R + 5); set_rd(A_STATUS); step; chk_rd(32'd0, OKAY, "old period end did not occur");
            go_to(R + 7); set_rd(A_COUNT); step;  chk_rd(32'd0, OKAY, "one-shot end after restart");
            go_to(R + 9); set_rd(A_CTRL); step;   chk_rd(32'd0, OKAY, "EN cleared, MODE 0");
            go_to(R + 11); set_rd(A_STATUS); step; chk_rd(32'd1, OKAY, "EXPIRED after restart end");
            go_to(R + 20); set_rd(A_COUNT); step; chk_rd(32'd0, OKAY, "no further end in one-shot");

            // ---- T7a: CTRL EN=1 on end edge (restart wins)
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 3); set_wr(A_CTRL, 32'h1, 4'h1); step;
            go_to(E + 4); set_rd(A_COUNT); step;   chk_rd(32'd3, OKAY, "CTRL EN=1 on end: restart");
            go_to(E + 6); set_rd(A_CTRL); step;    chk_rd(32'd1, OKAY, "EN stays 1 after restart on end");
            go_to(E + 8); set_rd(A_STATUS); step;  chk_rd(32'd1, OKAY, "EXPIRED set on collision");
            go_to(E + 10); set_rd(A_CTRL); step;   chk_rd(32'd0, OKAY, "second one-shot end clears EN");
            go_to(E + 12); set_rd(A_COUNT); step;  chk_rd(32'd0, OKAY, "COUNT 0 after second end");

            // ---- T7b: CTRL EN=0 (MODE->0) on periodic end: old MODE end value
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h5, 4'h1); step; E = cyc;
            go_to(E + 3); set_wr(A_CTRL, 32'h0, 4'h1); step;
            go_to(E + 4); set_rd(A_COUNT); step;   chk_rd(32'd3, OKAY, "EN=0 on periodic end: COUNT=LOAD");
            go_to(E + 6); set_rd(A_COUNT); step;   chk_rd(32'd3, OKAY, "COUNT held after stop on end");
            go_to(E + 8); set_rd(A_CTRL); step;    chk_rd(32'd0, OKAY, "CTRL after stop on end");
            go_to(E + 10); set_rd(A_STATUS); step; chk_rd(32'd1, OKAY, "EXPIRED set on stop/end edge");

            // ---- T7c: CTRL EN=0 (MODE->1) on one-shot end: old MODE end value
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 3); set_wr(A_CTRL, 32'h4, 4'h1); step;
            go_to(E + 4); set_rd(A_COUNT); step;   chk_rd(32'd0, OKAY, "EN=0 on one-shot end: COUNT=0");
            go_to(E + 6); set_rd(A_CTRL); step;    chk_rd(32'd4, OKAY, "CTRL MODE written, EN 0");
            go_to(E + 8); set_rd(A_COUNT); step;   chk_rd(32'd0, OKAY, "COUNT held at 0");
            go_to(E + 10); set_rd(A_STATUS); step; chk_rd(32'd1, OKAY, "EXPIRED set");

            // ---- T7d: LOAD write on periodic end (either outcome)
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h5, 4'h1); step; E = cyc;
            go_to(E + 3); set_wr(A_LOAD, 32'd7, 4'hF); step;
            go_to(E + 4); set_rd(A_COUNT); step;
            chk((last_rdata === 32'd3) || (last_rdata === 32'd7), "LOAD/end collision reload is old or new LOAD");
            ld_old = (last_rdata === 32'd3);
            go_to(E + 6); set_rd(A_COUNT); step;
            chk_rd(ld_old ? 32'd1 : 32'd5, OKAY, "COUNT after collision reload");
            go_to(E + 8); set_rd(A_COUNT); step;
            chk_rd(ld_old ? 32'd6 : 32'd3, OKAY, "new LOAD applies by next reload");
            wr(A_CTRL, 32'h0, 4'h1, OKAY);

            // ---- T7e: STATUS clear on one-shot end
            do_reset;
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h3, 4'h1); step; E = cyc;
            go_to(E + 3); chk(irq === 1'b0, "irq low before end");
            set_wr(A_STATUS, 32'h1, 4'h1); step;
            chk(irq === 1'b1, "end beats STATUS clear (one-shot)");
            rd(A_STATUS, 32'h1, OKAY);

            // ---- T8: LOAD 0, one-shot and periodic
            do_reset;
            wr(A_LOAD, 32'd0, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h3, 4'h1); step; E = cyc;
            chk(irq === 1'b0, "LOAD 0: irq low after start edge");
            go_to(E + 1); set_rd(A_COUNT); step;
            chk_rd(32'd0, OKAY, "LOAD 0: COUNT 0 from start edge");
            chk(irq === 1'b1, "LOAD 0: end on E+1");
            rd(A_CTRL, 32'h2, OKAY);
            wr(A_STATUS, 32'h1, 4'h1, OKAY);
            chk(irq === 1'b0, "LOAD 0 one-shot: cleared, no further end");
            set_wr(A_CTRL, 32'h7, 4'h1); step; E = cyc;
            chk(irq === 1'b0, "LOAD 0 periodic: irq low after start");
            tick;
            chk(irq === 1'b1, "LOAD 0 periodic: end on E+1");
            go_to(E + 3); set_wr(A_STATUS, 32'h1, 4'h1); set_rd(A_COUNT); step;
            chk(irq === 1'b1, "LOAD 0 periodic: end every edge beats clear");
            chk_rd(32'd0, OKAY, "LOAD 0 periodic: COUNT reads 0");
            go_to(E + 5); set_wr(A_CTRL, 32'h6, 4'h1); set_rd(A_CTRL); step;
            chk_rd(32'h7, OKAY, "LOAD 0 periodic: EN stays 1");
            wr(A_STATUS, 32'h1, 4'h1, OKAY);
            chk(irq === 1'b0, "after stop and clear irq low");
            for (i = 0; i < 5; i = i + 1) begin
                tick;
                chk(irq === 1'b0, "no end after stop");
            end
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_CTRL, 32'h6, OKAY);

            // ---- T9: transfers that do not disturb a running count
            do_reset;
            wr(A_LOAD, 32'd20, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h3, 4'h1); step; E = cyc;
            go_to(E + 2); set_rd(A_COUNT); step;
            chk_rd(32'd19, OKAY, "running COUNT after E+1");
            go_to(E + 3); set_wr(A_COUNT, 32'h0000FFFF, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, SLVERR}, "COUNT write SLVERR");
            go_to(E + 5); set_wr(8'h01, 32'hFFFFFFFF, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, SLVERR}, "misaligned write SLVERR");
            go_to(E + 7); set_wr(A_STATUS, 32'h0, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, OKAY}, "STATUS write 0 OKAY");
            go_to(E + 9); set_wr(A_CTRL, 32'h0, 4'b1110); step;
            chk_eq({30'd0, last_bresp}, {30'd0, OKAY}, "CTRL write without wstrb[0] OKAY");
            go_to(E + 11); set_wr(A_LOAD, 32'h5, 4'b0000); step;
            chk_eq({30'd0, last_bresp}, {30'd0, OKAY}, "LOAD write wstrb 0 OKAY");
            go_to(E + 13); set_wr(A_STATUS, 32'h1, 4'b1110); step;
            chk_eq({30'd0, last_bresp}, {30'd0, OKAY}, "STATUS write without wstrb[0] OKAY");
            go_to(E + 15); set_rd(8'h03); step;
            chk_rd(32'h0, SLVERR, "unmapped read during count");
            go_to(E + 17); set_rd(A_COUNT); step;
            chk_rd(32'd4, OKAY, "COUNT undisturbed after E+16");
            at(E + 19); chk(irq === 1'b0, "undisturbed: no early end");
            at(E + 20); chk(irq === 1'b1, "undisturbed: end exactly at E+N");
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_LOAD, 32'd20, OKAY);

            // ---- T10: full 32-bit decrement
            do_reset;
            wr(A_LOAD, 32'h00200000, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 2); set_rd(A_COUNT); step; chk_rd(32'h001FFFFF, OKAY, "32-bit borrow");
            go_to(E + 4); set_rd(A_COUNT); step; chk_rd(32'h001FFFFD, OKAY, "32-bit decrement");
            wr(A_CTRL, 32'h0, 4'h1, OKAY);
            do_reset;
            wr(A_LOAD, 32'h00200001, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h1, 4'h1); step; E = cyc;
            go_to(E + 2); set_rd(A_STATUS); step; chk_rd(32'h0, OKAY, "no end with upper COUNT bits set");
            go_to(E + 4); set_rd(A_COUNT); step; chk_rd(32'h001FFFFE, OKAY, "32-bit count continues");
            wr(A_CTRL, 32'h0, 4'h1, OKAY);

            // ---- T11: write ordering, early/late READY, stability
            do_reset;
            awaddr = A_LOAD; awvalid = 1'b1;
            chk(awready === 1'b1, "awready high when idle");
            tick; awvalid = 1'b0;
            chk((awready === 1'b0) && (wready === 1'b1) && (bvalid === 1'b0), "AW first: AW held, W ready, no B");
            tick; tick;
            chk((awready === 1'b0) && (wready === 1'b1) && (bvalid === 1'b0), "AW held while W absent");
            wdata = 32'hCAFEF00D; wstrb = 4'hF; wvalid = 1'b1;
            araddr = A_LOAD; arvalid = 1'b1; bready = 1'b0;
            tick; wvalid = 1'b0; arvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === OKAY), "AW first: B right after W accept edge");
            chk((rvalid === 1'b1) && (rresp === OKAY), "read accepted on completing edge");
            chk_eq(rdata, 32'h0, "read on completing edge returns pre-write LOAD");
            chk((awready === 1'b0) && (wready === 1'b0) && (arready === 1'b0), "readies low while responses wait");
            rready = 1'b0;
            awaddr = A_CTRL; wdata = 32'h0; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1;
            for (i = 0; i < 3; i = i + 1) begin
                tick;
                chk((bvalid === 1'b1) && (bresp === OKAY) && (awready === 1'b0) && (wready === 1'b0),
                    "B held while bready low; no AW/W accepted");
                chk((rvalid === 1'b1) && (arready === 1'b0), "R held while rready low");
                chk_eq(rdata, 32'h0, "rdata stable while rready low");
            end
            bready = 1'b1;
            tick;
            chk((bvalid === 1'b0) && (awready === 1'b1) && (wready === 1'b1), "B taken; write channels ready");
            tick; awvalid = 1'b0; wvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === OKAY), "waiting write completes after B");
            tick;
            chk(bvalid === 1'b0, "B taken with early bready");
            chk(rvalid === 1'b1, "R still held");
            chk_eq(rdata, 32'h0, "rdata does not follow LOAD write");
            rready = 1'b1;
            tick;
            chk((rvalid === 1'b0) && (arready === 1'b1), "R taken");
            rd(A_LOAD, 32'hCAFEF00D, OKAY);

            wdata = 32'h0BADBEEF; wstrb = 4'b0011; wvalid = 1'b1;
            tick; wvalid = 1'b0;
            chk((wready === 1'b0) && (awready === 1'b1) && (bvalid === 1'b0), "W first: W held");
            tick;
            chk((bvalid === 1'b0) && (wready === 1'b0), "W held while AW absent");
            awaddr = A_LOAD; awvalid = 1'b1;
            tick; awvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === OKAY), "W first: B right after AW accept edge");
            tick;
            rd(A_LOAD, 32'hCAFEBEEF, OKAY);

            wdata = 32'h1; wstrb = 4'hF; wvalid = 1'b1;
            tick; wvalid = 1'b0;
            awaddr = A_COUNT; awvalid = 1'b1;
            tick; awvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === SLVERR), "W-first COUNT write gets SLVERR");
            tick;
            awaddr = 8'h06; awvalid = 1'b1;
            tick; awvalid = 1'b0;
            wdata = 32'hFFFFFFFF; wstrb = 4'hF; wvalid = 1'b1;
            tick; wvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === SLVERR), "AW-first misaligned write gets SLVERR");
            tick;
            rd(A_LOAD, 32'hCAFEBEEF, OKAY);
            rd(A_COUNT, 32'h0, OKAY);

            wr(A_LOAD, 32'd100, 4'hF, OKAY);
            wr(A_CTRL, 32'h1, 4'h1, OKAY);
            rready = 1'b0;
            set_rd(A_COUNT); step;
            held_rdata = last_rdata;
            chk_eq(held_rdata, 32'd99, "COUNT sampled before AR accept edge");
            for (i = 0; i < 5; i = i + 1) begin
                tick;
                chk(rvalid === 1'b1, "rvalid held");
                chk_eq(rdata, held_rdata, "rdata frozen while count runs");
            end
            rready = 1'b1;
            tick;
            chk(rvalid === 1'b0, "R taken");
            wr(A_CTRL, 32'h0, 4'h1, OKAY);

            // ---- T12: reset during activity
            do_reset;
            wr(A_LOAD, 32'd2, 4'hF, OKAY);
            wr(A_CTRL, 32'h7, 4'h1, OKAY);
            repeat (3) tick;
            chk(irq === 1'b1, "periodic running with irq set");
            awaddr = A_LOAD; awvalid = 1'b1;
            tick; awvalid = 1'b0;
            chk(awready === 1'b0, "AW held before reset");
            rready = 1'b0; araddr = A_COUNT; arvalid = 1'b1;
            tick; arvalid = 1'b0;
            chk(rvalid === 1'b1, "R pending before reset");
            rst_n = 1'b0;
            tick;
            chk((irq === 1'b0) && (rvalid === 1'b0) && (bvalid === 1'b0), "reset edge clears irq/rvalid/bvalid");
            chk((awready === 1'b1) && (wready === 1'b1) && (arready === 1'b1), "reset edge clears held AW");
            rst_n = 1'b1; rready = 1'b1;
            rd(A_CTRL, 32'h0, OKAY);
            rd(A_LOAD, 32'h0, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);
            for (i = 0; i < 5; i = i + 1) begin
                tick;
                chk(irq === 1'b0, "count stopped by reset");
            end
            wdata = 32'h77; wstrb = 4'hF; wvalid = 1'b1;
            tick; wvalid = 1'b0;
            chk(bvalid === 1'b0, "no stale AW after reset");
            chk((wready === 1'b0) && (awready === 1'b1), "W held after reset");
            awaddr = A_LOAD; awvalid = 1'b1;
            tick; awvalid = 1'b0;
            chk((bvalid === 1'b1) && (bresp === OKAY), "write completes after reset");
            tick;
            rd(A_LOAD, 32'h77, OKAY);
            bready = 1'b0;
            set_wr(A_LOAD, 32'h5, 4'hF); step;
            rst_n = 1'b0;
            tick;
            chk((bvalid === 1'b0) && (awready === 1'b1) && (wready === 1'b1), "reset drops pending B");
            rst_n = 1'b1; bready = 1'b1;
            rd(A_LOAD, 32'h0, OKAY);
        end
    endtask

    // ---------------- width-8 only: upper offsets are unmapped ----------------
    task run_wide;
        begin
            do_reset;
            rd(8'h10, 32'h0, SLVERR);
            rd(8'h14, 32'h0, SLVERR);
            rd(8'h18, 32'h0, SLVERR);
            rd(8'h1C, 32'h0, SLVERR);
            rd(8'h40, 32'h0, SLVERR);
            rd(8'h84, 32'h0, SLVERR);
            rd(8'hFC, 32'h0, SLVERR);
            rd(8'h13, 32'h0, SLVERR);
            wr(8'h14, 32'hFFFFFFFF, 4'hF, SLVERR); rd(A_LOAD, 32'h0, OKAY);
            wr(8'h10, 32'h7, 4'hF, SLVERR);        rd(A_CTRL, 32'h0, OKAY);
            wr(8'hF8, 32'h1, 4'hF, SLVERR);        rd(A_COUNT, 32'h0, OKAY);
            wr(A_LOAD, 32'h12345678, 4'hF, OKAY);
            rd(8'h14, 32'h0, SLVERR);
            rd(8'h44, 32'h0, SLVERR);
            rd(A_LOAD, 32'h12345678, OKAY);

            wr(A_LOAD, 32'd10, 4'hF, OKAY);
            set_wr(A_CTRL, 32'h3, 4'h1); step; E = cyc;
            go_to(E + 2); set_wr(8'h10, 32'h0, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, SLVERR}, "0x10 write SLVERR");
            go_to(E + 4); set_wr(8'h40, 32'h1, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, SLVERR}, "0x40 write SLVERR");
            go_to(E + 6); set_wr(8'h14, 32'hFFFFFFFF, 4'hF); step;
            chk_eq({30'd0, last_bresp}, {30'd0, SLVERR}, "0x14 write SLVERR");
            go_to(E + 7); set_rd(8'h18); step;
            chk_rd(32'h0, SLVERR, "0x18 read during count");
            at(E + 9);  chk(irq === 1'b0, "wide: no early end");
            at(E + 10); chk(irq === 1'b1, "wide: end exactly at E+N");
            rd(A_LOAD, 32'd10, OKAY);
            rd(A_CTRL, 32'h2, OKAY);
            wr(8'h1C, 32'h1, 4'h1, SLVERR);
            rd(A_STATUS, 32'h1, OKAY);
            chk(irq === 1'b1, "0x1C write does not clear EXPIRED");
        end
    endtask

    // ---------------- main ----------------
    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        sel = 1'b0;
        run_suite;
        rst_n = 1'b0;
        tick;
        sel = 1'b1;
        run_suite;
        run_wide;
        chk(passed > 0, "at least one check passed");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // ---------------- watchdog ----------------
    initial begin
        #5000000;
        failed = failed + 1;
        $error("WATCHDOG: simulation did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
